import json
from itertools import permutations

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3]  # House numbers from left to right
    names = ["Peter", "Arnold", "Eric"]
    occupations = ["doctor", "teacher", "engineer"]
    hobbies = ["cooking", "photography", "gardening"]

    solutions = []

    # Iterate over all possible assignments
    for name_perm in permutations(names):
        for occ_perm in permutations(occupations):
            # Clue 5: The person who is an engineer is Peter.
            if name_perm.index("Peter") != occ_perm.index("engineer"):
                continue

            # Clue 1: The person who is a doctor and Eric are next to each other.
            if abs(occ_perm.index("doctor") - name_perm.index("Eric")) != 1:
                continue

            for hobby_perm in permutations(hobbies):
                # Clue 4: The photography enthusiast is the person who is a teacher.
                if hobby_perm[occ_perm.index("teacher")] != "photography":
                    continue

                # Clue 2: The person who loves cooking is directly left of the person who is a teacher.
                if hobby_perm.index("cooking") != occ_perm.index("teacher") - 1:
                    continue

                # Clue 3: The person who is a doctor is somewhere to the right of the person who enjoys gardening.
                if occ_perm.index("doctor") <= hobby_perm.index("gardening"):
                    continue

                # If all constraints are satisfied, record the solution
                solution = {
                    "name": list(name_perm),
                    "occupation": list(occ_perm),
                    "hobby": list(hobby_perm),
                }
                solutions.append(solution)

    # Expect exactly one solution
    if not solutions:
        raise ValueError("No solution found.")
    if len(solutions) > 1:
        # If multiple, choose the first (but typically Zebra puzzles yield a unique solution)
        solution = solutions[0]
    else:
        solution = solutions[0]

    # Build JSON output
    header = ["House", "name", "occupation", "hobby"]
    rows = []
    for i in range(len(houses)):
        rows.append([
            str(houses[i]),
            solution["name"][i],
            solution["occupation"][i],
            solution["hobby"][i],
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
